    startImport: {
        parameters: {
            query?: {
                /** @description An archive already on this machine, read in place. Mutually exclusive with a request body. */
                path?: string;
                /** @description An https link the server downloads and then sniffs. Mutually exclusive with `path` and with a request body. */
                url?: string;
                /** @description File name for a streamed body, used for the extension and for what the page displays. The extension decides which reader is used, so a 7z body must be named `.7z`. Defaults to `archive.zip`. */
                name?: string;
                /** @description Any value installs the sniffed job instead of starting a new one. */
                confirm?: string;
                /** @description Comma-separated indexes into `candidates`, for a caller with no JSON body to send. Used only with `confirm`. */
                pick?: string;
                /** @description Whether the caller's own source file survives a SUCCESSFUL import. Ignored unless IMPORT_KEEP is `ask`. Used only with `confirm`. */
                keep?: "0" | "1";
                /** @description Comma-separated indexes into `extras`: the companion files to download before installing. For a caller with no JSON body to send. Used only with `confirm`. */
                extras?: string;
            };
            header?: never;
            path?: never;
            cookie?: never;
        };
        /** @description The archive itself, streamed. Absent when `path` is given, and when confirming - where the body is instead the selection. */
        requestBody?: {
            content: {
                "application/zip": string;
                "application/x-7z-compressed": string;
                "application/octet-stream": string;
                "application/json": {
                    /** @description Indexes into `candidates`. */
                    pick?: number[];
                    /** @description Keep the source file after a successful import. Ignored unless IMPORT_KEEP is `ask`. */
                    keep?: boolean;
                    /** @description Indexes into `extras`: the companion files to download first. Omitted or empty downloads none of them. */
                    extras?: number[];
                };
            };
        };
        responses: {
            /** @description The archive was read; `candidates` is what it holds. */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["IntakeJob"];
                };
            };
            /** @description The extraction, or the download, is running. Poll `GET /api/intake`. */
            202: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["IntakeJob"];
                };
            };
            400: components["responses"]["BadRequest"];
            /** @description The link is not `https`, it resolves to an address on the local network, or IMPORT_URL_HOSTS is set and its host is not on the list. */
            403: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            /** @description An import is already running (the body then also carries `"busy": true`; `GET /api/intake` says which), there is nothing to confirm, no dictionary folder is configured, or a chosen dictionary is missing files it cannot work without. */
            409: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            /** @description The streamed archive is larger than this endpoint accepts. */
            413: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            /** @description Not an archive format this build can read - including a link that answered with something that is not an archive at all, which is refused from the response headers before the body is downloaded. */
            415: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            /** @description The archive was read and holds no dictionary, or its directory is larger than any bundle has cause to be. */
            422: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            500: components["responses"]["ServerError"];
        };
    };
